const periodWord=s=>({Daily:'day',Weekly:'week',Monthly:'month'}[s.period]||'period');
const periodComponentKey=(s,c)=>'output_'+periodWord(s)+'_'+outputSlug(c.name);
const externalComponentKey=(s,c)=>'output_'+periodWord(s)+'_'+outputSlug(s.name)+'_'+outputSlug(c.name);
const unitComponentKey=c=>'output_unit_'+outputSlug(c.name);
const externalUnitComponentKey=(s,c)=>'output_unit_'+outputSlug(s.name)+'_'+outputSlug(c.name);
function readUnitOutput(values,id){if(!values||!Object.hasOwn(values,id)||!Number.isFinite(values[id]))throw Error('The source payout has no output for this unit.');return values[id]}
function samePayoutWindow(a,b){return a.period===b.period&&(a.period!=='Weekly'||(a.weekStart||'Monday')===(b.weekStart||'Monday'))&&(a.period!=='Monthly'||Number(a.cycleStart||1)===Number(b.cycleStart||1))}
function compatibleStructure(a,b){return a.lob===b.lob&&a.entity===b.entity&&samePayoutWindow(a,b)}
for(const key of sharedKeys){const source=(bridge.fields||[]).find(f=>f.id===key.id);const period=source?.evaluationPeriod||source?.period||key.evaluationPeriod;if(['Daily','Weekly','Monthly'].includes(period))key.evaluationPeriod=period}
function periodKeyAllowed(k,s){return !k.evaluationPeriod||k.evaluationPeriod===s.period}
function outputTarget(token,source){for(const s of state.structures){if(s.id===source.id)continue;if(token===s.outputKey)return {s,c:null};for(const c of s.components)if(token===externalComponentKey(s,c))return {s,c};else if(c.basis==='Per Unit'&&token===externalUnitComponentKey(s,c))return {s,c,perUnit:true}}return null}
function scopeCheck(s,c,i){
 for(const k of c.keys||[]){const key=sharedKeys.find(x=>x.id===k);if(key&&!periodKeyAllowed(key,s))throw Error(key.name+' belongs to '+key.evaluationPeriod+' evaluations.');}
 const prior=s.components.slice(0,i),tokens=formulaIdentifiers(parsePayoutFormula(c.formula));
 for(const token of tokens){const registered=sharedKeys.find(k=>k.id===token||k.formulaKey===token);if(registered&&!periodKeyAllowed(registered,s))throw Error(registered.name+' belongs to '+registered.evaluationPeriod+' evaluations.');const raw=prior.find(p=>token===p.id||token===componentOutputKey(p));const unitSource=prior.find(p=>p.basis==='Per Unit'&&token===unitComponentKey(p));const aggregate=prior.find(p=>token===periodComponentKey(s,p));const target=outputTarget(token,s);
 if(c.basis==='Per Unit'&&(token==='running_payout'||raw||aggregate||(target&&!target.perUnit)))throw Error(c.name+': period totals cannot be used inside a per-unit formula. Use a Fixed component after aggregation.');
 if(unitSource&&(c.basis!=='Per Unit'||unitSource.unit!==c.unit))throw Error('Per-unit outputs require the same registered unit.');
 if(target?.perUnit&&(c.basis!=='Per Unit'||target.c.unit!==c.unit))throw Error('Per-unit outputs require the same registered unit.');
 if(c.basis==='Fixed'&&raw?.basis==='Per Unit')throw Error('Use '+periodComponentKey(s,raw)+' for the aggregated '+raw.name+' amount.');
 if(target&&!compatibleStructure(s,target.s))throw Error('Output references require the same entity and evaluation window.');
 }
}
structureOutputPlaceholders=function(s){const out={};for(const x of state.structures.filter(x=>x.id!==s.id&&compatibleStructure(x,s))){out[x.outputKey]=1000;for(const c of x.components){out[externalComponentKey(x,c)]=1000;if(c.basis==='Per Unit')out[externalUnitComponentKey(x,c)]=1000}}return out};
formulaKeyRows=function(c,i){ensureOutputNames(draft);const rows=[{token:'value',label:'Template value',description:'Value supplied by the Manager.'},...sharedKeys.filter(k=>(c.keys||[]).includes(k.id)&&periodKeyAllowed(k,draft)).map(k=>({token:formulaKey(k.id),label:k.name,description:draft.period+' evaluation'}))];
 if(c.basis==='Per Unit'){for(const a of state.units.find(u=>u.id===c.unit)?.attributes||[])if(numericType(a.type)||a.type==='Boolean')rows.push({token:a.name,label:a.name.replaceAll('_',' '),description:'Current unit attribute'});for(const p of draft.components.slice(0,i).filter(p=>p.basis==='Per Unit'&&p.unit===c.unit))rows.push({token:unitComponentKey(p),label:p.name,description:'Output for this same unit, before the Addition / Deduction operator.',scope:'Per unit'});for(const x of state.structures.filter(x=>x.id!==draft.id&&compatibleStructure(x,draft)))for(const p of x.components.filter(p=>p.basis==='Per Unit'&&p.unit===c.unit))rows.push({token:externalUnitComponentKey(x,p),label:p.name+' · '+x.name,description:'Output for the same rider and unit in this evaluation window.',scope:'Per unit'});return rows}
 rows.push({token:'running_payout',label:'Running payout',description:'Net amount before this component, for the same evaluation window.'});
 for(const x of draft.components.slice(0,i))rows.push({token:periodComponentKey(draft,x),label:x.name+' · '+draft.period+' total',description:'Aggregated component output before its Addition / Deduction operator.'});
 for(const x of state.structures.filter(x=>x.id!==draft.id&&compatibleStructure(x,draft))){rows.push({token:x.outputKey,label:x.name,description:'Net total for the same evaluation window.'});for(const p of x.components)rows.push({token:externalComponentKey(x,p),label:p.name+' · '+x.name,description:x.period+' component total. Requires an applicable template for the rider.'})}return rows;
};
availableKeysDropdown=function(c,i){const available=sharedKeys.filter(k=>periodKeyAllowed(k,draft)),selected=available.filter(k=>(c.keys||[]).includes(k.id));return `<div class="section-gap key-picker"><label>Available keys · ${esc(draft.period)}</label><details data-key-dropdown="${i}"><summary><span data-key-count="${i}">${selected.length?selected.length+' keys selected':'Select keys'}</span></summary><div class="key-options"><input type="search" data-key-search="${i}" placeholder="Search keys">${available.map(k=>`<label class="key-option" data-key-search-text="${esc((k.name+' '+formulaKey(k.id)).toLowerCase())}"><input type="checkbox" data-key-pick="${i}|${esc(k.id)}" ${(c.keys||[]).includes(k.id)?'checked':''}><span>${esc(k.name)}</span></label>`).join('')}</div></details><p class="quiet">Keys are evaluated for this structure's ${esc(draft.period.toLowerCase())} window.</p></div>`};
checkOutputDependencies=function(candidate){const all=state.structures.filter(s=>s.id!==candidate.id).concat(candidate),active=new Set(),done=new Set();function walk(s){if(active.has(s.id))throw Error('Circular payout output reference.');if(done.has(s.id))return;active.add(s.id);for(const c of s.components)for(const token of formulaIdentifiers(parsePayoutFormula(c.formula))){const x=all.find(x=>token===x.outputKey||x.components.some(p=>token===externalComponentKey(x,p)||(p.basis==='Per Unit'&&token===externalUnitComponentKey(x,p))));if(!x)continue;if(x.id===s.id)throw Error('Use an earlier component output within this structure.');if(!compatibleStructure(x,s))throw Error('Output references require the same evaluation window.');walk(x)}active.delete(s.id);done.add(s.id)}walk(candidate)};
const scopedValidate=validateStructure;
validateStructure=function(s){for(const [i,c] of s.components.entries())scopeCheck(s,c,i);const names=s.components.map(c=>periodComponentKey(s,c));if(new Set(names).size!==names.length)throw Error('Component names must be unique for their period output references.');scopedValidate(s)};
let scopedEvaluation=null;
calculate=function(t,u){const root=!scopedEvaluation;if(root)scopedEvaluation={active:new Set(),cache:new Map()};const context=scopedEvaluation,key=u.id+'|'+t.id;try{if(context.active.has(key))throw Error('Circular payout output reference.');if(context.cache.has(key))return context.cache.get(key);context.active.add(key);const s=structure(t.structure);t.components.forEach((c,i)=>scopeCheck({...s,components:t.components},c,i));const result=beforeOutputCalculate({...t,__resolveOutput:(token,record)=>{const target=outputTarget(token,s);if(!target||!compatibleStructure(s,target.s))throw Error('Output requires the same evaluation window.');const matches=[...new Set(assignmentsForUser(u).filter(a=>template(a.template)?.structure===target.s.id).map(a=>a.template))];if(matches.length!==1)throw Error('Exactly one applicable template is required for '+target.s.name);const result=calculate(template(matches[0]),u);if(target.perUnit){if(!record||record.unit!==target.c.unit)throw Error('Unit context is required.');return readUnitOutput(result.unitOutputs?.[target.c.id],record.id)}return target.c?result.lines[target.s.components.findIndex(c=>c.id===target.c.id)]?.amount:result.total}},u);context.cache.set(key,result);return result}finally{context.active.delete(key);if(root)scopedEvaluation=null}};
const payoutScopeLabel=s=>'Per '+periodWord(s);
const scopedFormulaRows=formulaKeyRows;
formulaKeyRows=function(c,i){const attributes=new Set((state.units.find(u=>u.id===c.unit)?.attributes||[]).map(a=>a.name));return scopedFormulaRows(c,i).map(row=>({...row,label:row.label.replace(/ · (Daily|Weekly|Monthly) total$/,''),scope:row.scope||(row.token==='value'?'Template value':c.basis==='Per Unit'&&attributes.has(row.token)?'Per unit':payoutScopeLabel(draft))}))};
renderFormulaKeys=function(i){return table(['Key','Reference',''],formulaKeyRows(draft.components[i],i).map(k=>row([`<div class="payout-key-name"><strong>${esc(k.label)}</strong><span class="payout-scope-tag">${esc(k.scope)}</span></div><small>${esc(k.description)}</small>`,`<code>${esc(k.token)}</code>`,`<button type="button" data-insert-formula="${i}" data-formula-token="${esc(k.token)}">Insert</button>`])))};
const scopePicker=availableKeysDropdown;
availableKeysDropdown=function(c,i){let html=scopePicker(c,i).replace('Available keys · '+esc(draft.period),'Choose data for this payout').replace('Select keys','Select data').replace('Search keys','Search data');for(const k of sharedKeys)html=html.replace(`<span>${esc(k.name)}</span>`,`<span class="payout-key-name">${esc(k.name)} <span class="payout-scope-tag">${esc(payoutScopeLabel(draft))}</span></span>`);if(c.basis==='Per Unit'){const attrs=state.units.find(u=>u.id===c.unit)?.attributes||[];html+=`<details class="section-gap"><summary>Available unit attributes</summary>${attrs.map(a=>`<div class="payout-unit-key"><span>${esc(a.name.replaceAll('_',' '))}</span><span class="payout-scope-tag">Per unit</span></div>`).join('')}</details>`}return html};

const pickerBeforeOutputs=availableKeysDropdown;
availableKeysDropdown=function(c,i){const html=pickerBeforeOutputs(c,i);const outputs=formulaKeyRows(c,i).filter(r=>r.token.startsWith('output_'));return html+(outputs.length?`<details class="section-gap"><summary>Payout outputs</summary>${outputs.map(r=>`<div class="payout-unit-key"><span>${esc(r.label)} <span class="payout-scope-tag">${esc(r.scope)}</span></span><button type="button" data-insert-formula="${i}" data-formula-token="${esc(r.token)}">Insert</button></div>`).join('')}</details>`:'')};
